lessons.push(...[{"name":"Names and Countries","level":"Starter","word":"My name is Maya.","mm":"ကျွန်မနာမည် မာယာပါ။","text":"Say My name is followed by your name.","question":"Which sentence introduces your name?","opts":["My name is Maya.","I name yesterday.","Name is eating."],"correct":0,"writing":"Introduce yourself with your name and country."},{"name":"Numbers and Prices","level":"Starter","word":"It costs five dollars.","mm":"ငါးဒေါ်လာ ကျပါတယ်။","text":"Prices in the United States are often spoken in dollars and cents.","question":"Which answer gives a price?","opts":["I am happy.","It costs five dollars.","She is tall."],"correct":1,"writing":"Write the price of two things you buy."},{"name":"Days and Time","level":"Starter","word":"It is Monday morning.","mm":"တနင်္လာနေ့ မနက်ဖြစ်ပါတယ်။","text":"Use on with days: on Monday; at with clock times: at nine.","question":"Which phrase is correct?","opts":["at Monday","on Monday","in nine o’clock"],"correct":1,"writing":"Write the day and time of your next class."},{"name":"Please and Thank You","level":"Starter","word":"Thank you for your help.","mm":"ကူညီပေးတဲ့အတွက် ကျေးဇူးတင်ပါတယ်။","text":"Please makes requests more polite. Thank you shows appreciation.","question":"Which is polite?","opts":["Move now.","Please help me.","You help yesterday."],"correct":1,"writing":"Write a polite request and a thank-you sentence."},{"name":"At the Coffee Shop","level":"Beginner","word":"Could I have a small coffee, please?","mm":"ကော်ဖီအသေးတစ်ခွက် ရနိုင်မလား။","text":"Use Could I have to make a polite request.","question":"Which is a polite order?","opts":["Coffee now!","Could I have a coffee, please?","Coffee is running."],"correct":1,"writing":"Order a drink and ask its price."},{"name":"Family and Friends","level":"Beginner","word":"This is my older sister.","mm":"ဒါက ကျွန်မရဲ့ အစ်မပါ။","text":"Use this is to introduce someone nearby.","question":"Which introduces a family member?","opts":["This is my brother.","I am brother yesterday.","Brother is a place."],"correct":0,"writing":"Write three sentences about your family."},{"name":"Daily Routines","level":"Beginner","word":"I usually leave home at eight.","mm":"ကျွန်တော် ပုံမှန်အားဖြင့် ရှစ်နာရီမှာ အိမ်ကထွက်ပါတယ်။","text":"Use usually for habits and the present simple for routines.","question":"Which sentence describes a routine?","opts":["I usually walk to work.","I walked tomorrow.","Usually I am yesterday."],"correct":0,"writing":"Describe your morning routine in three sentences."},{"name":"Asking for Help","level":"Beginner","word":"Excuse me, could you help me?","mm":"တစ်ဆိတ်လောက်၊ ကူညီပေးနိုင်မလား။","text":"Excuse me gets attention politely.","question":"Which phrase asks for help?","opts":["Could you help me?","You are help.","I helped tomorrow."],"correct":0,"writing":"Write a request for help at a store."},{"name":"At the Grocery Store","level":"Elementary","word":"Where can I find the rice?","mm":"ဆန်ကို ဘယ်နေရာမှာ ရှာရမလဲ။","text":"Use Where can I find to ask for a product location.","question":"Which asks for a location?","opts":["How old is rice?","Where can I find the rice?","Rice is tomorrow."],"correct":1,"writing":"Ask a store employee for two products."},{"name":"Public Transportation","level":"Elementary","word":"Does this bus stop downtown?","mm":"ဒီဘတ်စ်ကားက မြို့လယ်မှာ ရပ်ပါသလား။","text":"Use Does this bus for questions about a route.","question":"Which asks about a bus route?","opts":["Does this bus go downtown?","This bus ate downtown.","Downtown is bus."],"correct":0,"writing":"Ask about a bus route and fare."},{"name":"Making Appointments","level":"Elementary","word":"Is there an opening on Friday?","mm":"သောကြာနေ့မှာ ချိန်းဆိုချိန်လွတ် ရှိပါသလား။","text":"An opening means an available appointment time.","question":"What does an opening mean here?","opts":["An available time","An open window","A new building"],"correct":0,"writing":"Write a message requesting an appointment."},{"name":"Past Weekend","level":"Elementary","word":"I visited my cousin last weekend.","mm":"ပြီးခဲ့တဲ့ စနေတနင်္ဂနွေမှာ ဝမ်းကွဲကို သွားတွေ့ခဲ့ပါတယ်။","text":"Use the simple past for completed actions.","question":"Which sentence uses the past correctly?","opts":["I visit yesterday.","I visited yesterday.","I will visited yesterday."],"correct":1,"writing":"Write four sentences about last weekend."},{"name":"Giving Updates at Work","level":"Intermediate","word":"I have finished the first draft.","mm":"ပထမမူကြမ်းကို ပြီးစီးထားပါပြီ။","text":"Present perfect can connect a completed task to the current situation.","question":"Which is a clear update?","opts":["I have finished the draft.","I finish yesterday tomorrow.","The draft is eating."],"correct":0,"writing":"Write a short project update to your supervisor."},{"name":"Explaining a Problem","level":"Intermediate","word":"The printer stopped working this morning.","mm":"ဒီမနက် ပရင်တာ အလုပ်မလုပ်တော့ပါဘူး။","text":"Explain what happened, when it happened, and what help you need.","question":"Which sentence explains a problem?","opts":["The printer stopped working.","The printer is a movie.","Tomorrow was printer."],"correct":0,"writing":"Describe a workplace problem and request help."},{"name":"Small Talk with Coworkers","level":"Intermediate","word":"How was your weekend?","mm":"စနေတနင်္ဂနွေ ဘယ်လိုဖြတ်သန်းခဲ့လဲ။","text":"Small talk is friendly informal conversation, not a formal interview.","question":"Which is suitable small talk?","opts":["How was your weekend?","Give me your password.","Why are you late every day?"],"correct":0,"writing":"Write a friendly two-turn conversation."},{"name":"Sharing an Opinion","level":"Intermediate","word":"I think public transit is convenient.","mm":"အများပြည်သူသယ်ယူပို့ဆောင်ရေးက အဆင်ပြေတယ်လို့ ထင်ပါတယ်။","text":"Use I think and because to explain an opinion.","question":"Which gives a reason?","opts":["I prefer trains because they are convenient.","Trains because yes.","I am convenient yesterday."],"correct":0,"writing":"Write your opinion about working from home."},{"name":"Clarifying Misunderstandings","level":"Upper Intermediate","word":"I may have misunderstood your request.","mm":"သင့်တောင်းဆိုချက်ကို ကျွန်တော် နားလည်မှုလွဲခဲ့နိုင်ပါတယ်။","text":"Acknowledge possible misunderstanding without blaming the other person.","question":"Which response is diplomatic?","opts":["You explained badly.","I may have misunderstood.","You are always wrong."],"correct":1,"writing":"Write a diplomatic clarification email."},{"name":"Customer Service Complaints","level":"Upper Intermediate","word":"I was charged twice for the same item.","mm":"ပစ္စည်းတစ်ခုတည်းအတွက် နှစ်ကြိမ် ငွေဖြတ်ခံရပါတယ်။","text":"State the problem factually and ask for a specific resolution.","question":"Which is factual?","opts":["You always cheat.","I was charged twice.","Your store is terrible."],"correct":1,"writing":"Write a concise refund request."},{"name":"Comparing Options","level":"Upper Intermediate","word":"The second option is more cost-effective.","mm":"ဒုတိယရွေးချယ်မှုက ကုန်ကျစရိတ် ပိုသက်သာထိရောက်ပါတယ်။","text":"Compare alternatives using evidence and trade-offs.","question":"Which compares options?","opts":["Both options are blue.","The second option costs less.","Options yesterday."],"correct":1,"writing":"Compare two commuting choices."},{"name":"Negotiating a Schedule","level":"Upper Intermediate","word":"Would it be possible to move the meeting?","mm":"အစည်းအဝေးအချိန်ကို ရွှေ့လို့ရနိုင်မလား။","text":"A polite conditional question softens a scheduling request.","question":"Which request is tactful?","opts":["Move it now.","Would it be possible to reschedule?","You must change everything."],"correct":1,"writing":"Write a scheduling request with an alternative time."},{"name":"Leading a Meeting","level":"Advanced","word":"Before we begin, let us clarify our objectives.","mm":"မစတင်ခင် ရည်ရွယ်ချက်တွေကို ရှင်းလင်းသတ်မှတ်ကြရအောင်။","text":"Set the agenda, invite contributions, and summarize next steps.","question":"Which opens a meeting effectively?","opts":["Let us clarify our objectives.","Nobody should speak.","We have no plan ever."],"correct":0,"writing":"Draft a brief meeting opening."},{"name":"Presenting a Proposal","level":"Advanced","word":"The evidence suggests a phased approach.","mm":"အထောက်အထားတွေက အဆင့်လိုက်လုပ်ဆောင်နည်းကို ညွှန်ပြနေပါတယ်။","text":"Use cautious language when evidence supports but does not prove a conclusion.","question":"Which is appropriately cautious?","opts":["The evidence suggests...","This proves everything forever.","No evidence matters."],"correct":0,"writing":"Write a proposal summary with one risk."},{"name":"Constructive Feedback","level":"Advanced","word":"One area we could strengthen is clarity.","mm":"ပိုကောင်းအောင် လုပ်နိုင်တဲ့အပိုင်းတစ်ခုက ရှင်းလင်းမှုပါ။","text":"Give specific, actionable feedback without attacking the person.","question":"Which is constructive?","opts":["You are bad at this.","We could improve the introduction.","This is hopeless."],"correct":1,"writing":"Write constructive feedback on a presentation."},{"name":"Handling Disagreement","level":"Advanced","word":"I appreciate your perspective, although I see it differently.","mm":"သင့်အမြင်ကို လေးစားပါတယ်၊ ဒါပေမယ့် ကျွန်တော့်အမြင်က ကွာခြားပါတယ်။","text":"Recognize the other perspective before explaining disagreement.","question":"Which is respectful?","opts":["Your view is nonsense.","I see it differently, and here is why.","Stop talking."],"correct":1,"writing":"Write a respectful disagreement with a reason."},{"name":"Reading Between the Lines","level":"Expert","word":"The proposal leaves several questions unanswered.","mm":"အဆိုပြုချက်မှာ မဖြေရှင်းရသေးတဲ့ မေးခွန်းအချို့ ကျန်နေပါတယ်။","text":"Identify implications, assumptions, and what a speaker avoids saying.","question":"What is implied?","opts":["Every detail is settled.","Some issues remain unresolved.","The proposal is a book."],"correct":1,"writing":"Explain two unstated assumptions in a proposal."},{"name":"Nuanced Recommendations","level":"Expert","word":"On balance, I would recommend a gradual rollout.","mm":"အချက်အားလုံးချိန်ဆပြီး အဆင့်လိုက်စတင်ဖို့ အကြံပြုချင်ပါတယ်။","text":"On balance signals a judgment after weighing competing considerations.","question":"What does on balance signal?","opts":["A weighted judgment","A bank balance","An exact measurement"],"correct":0,"writing":"Write a recommendation with trade-offs."},{"name":"Diplomatic Refusals","level":"Expert","word":"I am afraid we cannot commit to that timeline.","mm":"အဲဒီအချိန်ဇယားကို လိုက်နာမယ်လို့ ကတိမပေးနိုင်ပါဘူး။","text":"A diplomatic refusal states a boundary and may offer an alternative.","question":"Which refusal is diplomatic?","opts":["Absolutely not, never.","We cannot commit to that timeline, but we can discuss alternatives.","Your idea is ridiculous."],"correct":1,"writing":"Decline a request while proposing another option."},{"name":"Interpreting Tone","level":"Expert","word":"That is an interesting point worth exploring.","mm":"ဒါက ဆက်လက်ဆွေးနွေးသင့်တဲ့ စိတ်ဝင်စားစရာအချက်ပါ။","text":"Tone depends on context and delivery; the same phrase may sound sincere or reserved.","question":"What affects implied tone?","opts":["Only the dictionary","Context and delivery","Only punctuation"],"correct":1,"writing":"Write two interpretations of a workplace comment."},{"name":"Crisis Communication","level":"Pro","word":"Our immediate priority is to ensure everyone is safe.","mm":"အခုချက်ချင်း ဦးစားပေးရမှာ လူတိုင်း ဘေးကင်းဖို့ပါ။","text":"In a crisis, communicate verified facts, immediate actions, and next updates.","question":"Which is appropriate?","opts":["Share unverified rumors.","State verified facts and next steps.","Promise impossible results."],"correct":1,"writing":"Draft a short incident update without speculation."},{"name":"Cross-Team Leadership","level":"Pro","word":"Let us establish clear owners and milestones.","mm":"တာဝန်ခံတွေနဲ့ အဓိကအဆင့်တွေကို ရှင်းရှင်းလင်းလင်း သတ်မှတ်ကြရအောင်။","text":"Good coordination identifies decisions, owners, dates, and dependencies.","question":"What makes an action item clear?","opts":["An owner and deadline","A vague hope","No responsibility"],"correct":0,"writing":"Write three action items with owners and dates."},{"name":"Stakeholder Negotiation","level":"Pro","word":"We can revisit the scope if the constraints change.","mm":"ကန့်သတ်ချက်တွေ ပြောင်းလဲရင် လုပ်ငန်းအကျယ်အဝန်းကို ပြန်သုံးသပ်နိုင်ပါတယ်။","text":"Effective negotiation distinguishes interests, constraints, and concessions.","question":"Which is conditional negotiation?","opts":["We can revisit scope if constraints change.","Everything is fixed forever.","There are no constraints."],"correct":0,"writing":"Draft a conditional agreement and next steps."},{"name":"Executive Briefing","level":"Pro","word":"The key takeaway is that the pilot met its primary goal.","mm":"အဓိကအနှစ်ချုပ်က စမ်းသပ်အစီအစဉ်က ပင်မရည်မှန်းချက်ကို ပြည့်မီခဲ့တာပါ။","text":"Executive briefings prioritize outcomes, evidence, risks, and decisions.","question":"Which is a clear takeaway?","opts":["The pilot met its primary goal.","Many things happened.","We have some slides."],"correct":0,"writing":"Write a five-sentence executive briefing."}]);

