const expressions=[['What’s up?','ဘာထူးလဲ။','Informal greeting among friends.'],['No worries.','ကိစ္စမရှိပါဘူး။','Friendly response to an apology or thanks.'],['I’m down.','ကျွန်တော်လည်း ပါမယ်။','Casual agreement to a plan.'],['Break a leg!','အောင်မြင်ပါစေ။','Encouragement before a performance.'],['Hit the road.','ခရီးစထွက်မယ်။','Informal expression for leaving on a trip.'],['Sounds good.','ကောင်းပါတယ်။','Natural agreement in everyday conversation.']];
const pages=[['home','🏠','Home'],['academy','🎓','Academy'],['world','🗺️','World'],['speak','🎙️','Speak'],['profile','👤','Profile']];let state;try{state=JSON.parse(localStorage.getItem('eausa_progress')||'null')}catch{};if(!state||!Array.isArray(state.completed)||!Array.isArray(state.missions))state={xp:0,completed:[],missions:[],writing:{}};state.writing ||= {};state.xp ||= 0;let academyLevel=0,page='home',selectedLesson=0,selectedPlace=0,choice=-1,missionChoice=-1,feedback='',missionFeedback='',expr=0,recognized='';function updateGuest(){let el=document.getElementById('guestName');state.guestName=(el?.value||'').trim().slice(0,40)||'English Explorer';state.avatar=document.getElementById('guestAvatar')?.value||'🧑‍🎓';save();render()}
function exportProgress(){const payload={version:1,created:new Date().toISOString(),progress:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='english-adventure-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function importProgress(input){const file=input.files?.[0];if(!file)return;if(file.size>1024*1024){alert('Backup file is too large.');return}const reader=new FileReader();reader.onload=()=>{try{const payload=JSON.parse(reader.result);const d=payload.progress;if(!d||!Array.isArray(d.completed)||!Array.isArray(d.missions)||!Number.isFinite(d.xp)||d.xp<0||typeof d.writing!=='object'||!d.writing||Array.isArray(d.writing))throw Error('Invalid backup');if(!confirm('Replace current guest progress with this backup?'))return;state={xp:Math.min(d.xp,10000000),completed:d.completed.filter(x=>typeof x==='string').slice(0,2000),missions:d.missions.filter(x=>typeof x==='string').slice(0,200),writing:Object.fromEntries(Object.entries(d.writing).filter(([k,v])=>typeof k==='string'&&typeof v==='string').slice(0,1000)),guestName:String(d.guestName||'English Explorer').slice(0,40),avatar:['🧑‍🎓','👩‍🎓','👨‍🎓','🧑‍💼','👩‍💼'].includes(d.avatar)?d.avatar:'🧑‍🎓'};save();render()}catch(e){alert('This is not a valid English Adventure progress backup.')}};reader.readAsText(file)}
function save(){try{localStorage.setItem('eausa_progress',JSON.stringify(state))}catch(e){console.warn('Local storage unavailable',e)};document.getElementById('xp').textContent=state.xp}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function nav(p){if(typeof stopMiniClip==='function')stopMiniClip();page=p;feedback='';missionFeedback='';render();window.scrollTo(0,0)}function speak(s){if(!('speechSynthesis'in window)){alert('Speech synthesis is not available in this browser.');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(s);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u)}function award(key,amount){if(!state.completed.includes(key)){state.completed.push(key);state.xp+=amount;save();return true}return false}function header(title,sub){return `<h1>${title}</h1><p class="muted">${sub}</p>`}function render(){document.getElementById('nav').innerHTML=pages.map(([id,icon,name])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')">${icon} ${name}</button>`).join('');document.getElementById('bottom').innerHTML=pages.map(([id,icon,name])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')"><span>${icon}</span>${name}</button>`).join('');save();let a=document.getElementById('app');if(page==='home'){a.innerHTML=`<section class="hero hero-upgraded"><div><span class="tag">✨ Learn • Explore • Speak</span><h1>Your English Adventure<br>Starts Here!</h1><p>အမေရိကန်နေ့စဉ်ဘဝကို စူးစမ်းရင်း Listening, Reading, Writing, Speaking လေးမျိုးစလုံး လေ့ကျင့်ပါ။</p><div class="row"><button class="btn white" onclick="nav('academy')">🎓 Start Academy →</button><button class="btn glass" onclick="nav('world')">🗺️ Explore World</button></div></div><img class="hero-picture" src="/art/city.svg" alt="Illustrated American adventure city"></section><h2 class="section">Four Essential English Skills</h2><div class="skills-grid">${skillInfo.map(([icon,name,desc,slug])=>`<button class="skill-card" onclick="nav('${slug==='speak'?'speak':'academy'}')"><img src="/art/${slug}.svg" alt="${name} illustration" loading="lazy"><span class="skill-title">${icon} ${name}</span><small>${desc}</small><span class="card-arrow">Explore →</span></button>`).join('')}</div><h2 class="section">Your Learning Journey • 8 Levels</h2><div class="level-grid">${levelInfo.map(([name,cefr,desc,icon],i)=>`<button class="level-card" onclick="academyLevel=${i};page='academy';render()"><img class="level-scene" src="/art/levels/level-${i+1}.svg" alt="${esc(name)} learning illustration" loading="lazy" onerror="this.onerror=null;this.src='/art/levels/level-1.svg'"><span class="level-number">LEVEL ${i+1} · ${cefr}</span><strong>${name}</strong><small>${desc}</small><span class="card-arrow">Open Lesson →</span></button>`).join('')}</div><h2 class="section">Adventure World • 24 Places</h2><div class="world-preview"><img src="/art/city.svg" alt="Colorful adventure world" loading="lazy"><div><h3>Practice English Across America</h3><p>Restaurant, Airport, Hospital, Workplace, Cinema, Museum and more!</p><button class="btn" onclick="nav('world')">🌎 Explore 24 Missions →</button></div></div><h2 class="section">Today's American Expression</h2><div class="card expression-card"><span class="tag">🇺🇸 Daily English</span><div class="expression">${esc(expressions[expr][0])}</div><p>${esc(expressions[expr][1])}</p><p class="muted">${esc(expressions[expr][2])}</p><div class="row"><button class="btn secondary" onclick="speak(expressions[expr][0])">🔊 Listen</button><button class="btn secondary" onclick="expr=(expr+1)%expressions.length;render()">Next →</button></div></div>`}
if(page==='academy'){a.innerHTML=header('🎓 English Academy','8 Levels • 80 Guided Lessons • Listening, Reading, Writing & Speaking')+`<div class="level-tabs">${levelInfo.map((info,i)=>`<button class="${academyLevel===i?'selected':''}" onclick="academyLevel=${i};render()">${info[3]} ${info[0]}</button>`).join('')}</div><div class="level-grid">${lessons.map((l,i)=>({...l,index:i})).filter(l=>l.level===levelInfo[academyLevel][0]).map(l=>`<div class="level-card academy-card"><img class="lesson-art" src="/art/lessons/${lessonSlug(l.name)}.svg" alt="Illustration for ${esc(l.name)}" loading="lazy"><span class="level-number">LEVEL ${academyLevel+1} · ${levelInfo[academyLevel][1]}</span><h3>${esc(l.level)}</h3><p>${esc(l.name)}</p><small>🎧 Listen · 📖 Read · ✍️ Write · 🎙️ Speak</small><p class="muted">${state.completed.includes('lesson'+l.index)?'✅ Sample completed':'⭐ +40 XP'}</p><button class="btn" onclick="selectedLesson=${l.index};choice=-1;feedback='';page='lesson';render()">Open Lesson →</button></div>`).join('')}</div><div class="notice">80 guided sample lessons across 8 levels. These are prototypes, not an accredited proficiency assessment. The 540-lesson curriculum remains a future target.</div>`}
if(page==='lesson'){let l=lessons[selectedLesson];academyLevel=levelInfo.findIndex(x=>x[0]===l.level);a.innerHTML=`<div class="lesson"><button class="btn secondary" onclick="nav('academy')">← Academy</button><h1>${esc(l.name)}</h1><span class="tag">${l.level} • Lesson ${selectedLesson+1}</span><div class="card" style="margin-top:15px"><h2>1. 📚 Learn & 2. 🎧 Listen</h2><h2>${esc(l.word)}</h2><p>${esc(l.mm)}</p><div class="row"><button class="btn" onclick="speak(lessons[selectedLesson].word)">🔊 Play American English</button><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">↻ Repeat</button></div></div><div class="card scene-card" style="margin-top:14px"><h2>🎬 Animated Conversation Clip</h2><div class="scene-stage"><div class="scene-person">🧑‍🏫</div><div class="scene-bubble" id="sceneBubble">Press Play to watch a short conversation.</div><div class="scene-person">🧑‍🎓</div></div><div class="row"><button class="btn" onclick="playScene()">▶ Play Scene</button><button class="btn secondary" onclick="stopScene()">■ Stop</button></div><p class="muted">Animated captions with browser speech; not a filmed video.</p></div><div class="card" style="margin-top:14px"><h2>3. 📖 Read</h2><p>${esc(l.text)}</p><button class="btn secondary" onclick="speak(lessons[selectedLesson].text)">🔊 Read aloud</button></div><div class="card" style="margin-top:14px"><h2>7. 🏆 Review & Mastery</h2><p>${esc(l.question)}</p><div class="choices">${l.opts.map((o,i)=>`<button class="choice ${choice===i?'selected':''}" onclick="choice=${i};feedback='';render()">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="btn" onclick="checkLesson()">Check Answer</button>${feedback?`<div class="feedback ${feedback.startsWith('Try')?'bad':''}">${feedback}</div>`:''}</div><div class="card" style="margin-top:14px"><h2>5. ✍️ Write</h2><p>${esc(l.writing)}</p><textarea class="field" id="writing" oninput="state.writing['lesson'+selectedLesson]=this.value;save()" placeholder="Write your English here...">${esc(state.writing['lesson'+selectedLesson]||'')}</textarea><button class="btn secondary" onclick="state.writing['lesson'+selectedLesson]=document.getElementById('writing').value;save();alert('Writing saved on this device. This prototype does not automatically grade free-form writing.')">💾 Save Writing</button></div><div class="card" style="margin-top:14px"><h2>4. 🎙️ Speak</h2><p>Listen, then repeat: <strong>${esc(l.word)}</strong></p><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">🔊 Hear sentence</button> <button class="btn" onclick="listen()">🎙️ Try microphone</button><p class="muted" id="speechResult">Microphone recognition depends on your browser and permissions.</p></div><div class="card" style="margin-top:14px"><h2>6. 🌎 Real-Life Mission</h2><p>Practice this English in a real-world scenario.</p><button class="btn" onclick="nav('world')">Choose a Mission →</button></div>${lessonDialogue(l)}${individualStudio(l)}${conversationLab(l)}${reviewLab(l)}${masteryStudio(l)}${scenarioStudio(l)}${storyboardStudio(l)}</div>`}
if(page==='world'){a.innerHTML=header('🗺️ American Adventure World','Choose a location. Meet a character. Complete a real-life English mission.')+`<div class="world-banner"><img src="/art/city.svg" alt="Illustrated city map"></div><div class="world">${places.map((p,i)=>`<button class="place" onclick="selectedPlace=${i};missionChoice=-1;missionFeedback='';page='mission';render()"><span class="emoji">${p.icon}</span><strong>${p.name}</strong><small>${p.desc}</small><p>${state.missions.includes(p.id)?'🏆 Mission completed':'🎯 Play mission →'}</p></button>`).join('')}</div><div class="notice">🌟 All 24 locations have a playable guided sample mission. More dialogue branches and difficulty levels will be added in the full curriculum.</div>`}
if(page==='mission'){let p=places[selectedPlace];a.innerHTML=`<div class="lesson"><button class="btn secondary" onclick="nav('world')">← Adventure World</button><h1>${p.icon} ${p.name} Mission</h1><span class="tag">Real-Life English • +30 XP</span><div class="card" style="margin-top:15px"><div class="big">${p.icon} 🧑‍💼</div><h2>Character says:</h2><div class="dialogue"><h2>“${esc(p.line)}”</h2><p class="muted">${esc(p.mm)}</p></div><button class="btn secondary" onclick="speak(places[selectedPlace].line)">🔊 Listen to character</button></div><div class="card" style="margin-top:14px"><h2>🎯 Your turn</h2><p>${esc(p.q)}</p><div class="choices">${p.opts.map((o,i)=>`<button class="choice ${missionChoice===i?'selected':''}" onclick="missionChoice=${i};missionFeedback='';render()">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="btn" onclick="checkMission()">Submit Answer</button>${missionFeedback?`<div class="feedback ${missionFeedback.startsWith('Try')?'bad':''}">${missionFeedback}</div>`:''}</div></div>`}
if(page==='speak'){a.innerHTML=header('🎙️ Speaking Studio','Listen and repeat • American English practice')+`<div class="grid">${['Nice to meet you.','Could I have a coffee, please?','Can you tell me how to get there?','I would be happy to help.','Could we schedule a meeting?','Thank you. I really appreciate it.'].map((s,i)=>`<div class="card"><span class="tag">Practice ${i+1}</span><h3>${s}</h3><div class="row"><button class="btn secondary" onclick="speak(${JSON.stringify(s).replace(/"/g,'&quot;')})">🔊 Listen</button><button class="btn" onclick="listen()">🎙️ Speak</button></div></div>`).join('')}</div><div class="card"><h3>Microphone feedback</h3><p id="speechResult">Click Speak, allow microphone access, and try a sentence. Recognized words are shown here when supported.</p><p class="notice">Speech recognition is browser-dependent and may use an online service. This prototype shows recognized words; it does not calculate a pronunciation score.</p></div>`}
if(page==='profile'){a.innerHTML=header('👤 My Learning Journey','No login required • Saved on this device')+`<section class="guest-card"><div class="guest-avatar">${esc(state.avatar||'🧑‍🎓')}</div><div class="guest-details"><h2>My Guest Profile</h2><p class="muted">Learn immediately without creating an account. Export your progress before clearing browser data.</p><label for="guestName">Nickname</label><input id="guestName" maxlength="40" value="${esc(state.guestName||'English Explorer')}" placeholder="Your nickname"><label for="guestAvatar">Choose an avatar</label><select id="guestAvatar">${['🧑‍🎓','👩‍🎓','👨‍🎓','🧑‍💼','👩‍💼'].map(x=>`<option value="${x}" ${x===(state.avatar||'🧑‍🎓')?'selected':''}>${x}</option>`).join('')}</select><div class="row guest-actions"><button class="btn" onclick="updateGuest()">Save Profile</button><button class="btn secondary" onclick="exportProgress()">⬇ Export Backup</button><label class="btn secondary import-label" for="importBackup">⬆ Import Backup</label><input id="importBackup" type="file" accept=".json,application/json" onchange="importProgress(this)" hidden></div></div></section>`+`<div class="grid"><div class="card"><div class="big">⭐</div><div class="stat">${state.xp}</div><strong>Total XP</strong></div><div class="card"><div class="big">🎓</div><div class="stat">${state.completed.filter(x=>x.startsWith('lesson')).length} / ${lessons.length}</div><strong>Sample Lessons</strong></div><div class="card"><div class="big">🏆</div><div class="stat">${state.missions.length} / ${places.length}</div><strong>World Missions</strong></div></div><div class="card"><h2>Learning Progress</h2><p>Academy Lessons</p><div class="bar"><div style="width:${100*state.completed.filter(x=>x.startsWith('lesson')).length/lessons.length}%"></div></div><p>Adventure Missions</p><div class="bar"><div style="width:${100*state.missions.length/places.length}%"></div></div><p class="muted">These numbers describe only this prototype, not an official English proficiency score.</p><button class="btn secondary" onclick="if(confirm('Reset all local prototype progress?')){state={xp:0,completed:[],missions:[],writing:{},guestName:state.guestName,avatar:state.avatar};save();render()}">Reset Prototype Progress</button></div>`}
}
function lessonExtras(l){
 const phrase=l.word.replace(/[.!?]+$/,'');
 const scenario=l.name.toLowerCase();
 const partner=scenario.includes('restaurant')||scenario.includes('coffee')?'Server':scenario.includes('work')||scenario.includes('meeting')?'Coworker':scenario.includes('airport')||scenario.includes('travel')?'Agent':scenario.includes('store')||scenario.includes('shopping')?'Clerk':'Local';
 const open=partner==='Server'?'Hi there! What can I get for you?':partner==='Coworker'?'Hi! Do you have a minute?':partner==='Agent'?'Hello! How can I help you today?':partner==='Clerk'?'Welcome! Are you looking for anything?':'Hello! How can I help you?';
 const vocab=[...new Set(l.word.toLowerCase().match(/[a-z]+(?:'[a-z]+)?/g)||[])].filter(w=>w.length>3).slice(0,5);
 return {partner,turns:[{who:partner,line:open},{who:'You',line:l.word},{who:partner,line:'Of course! Let me help you with that.'},{who:'You',line:'Thank you. I appreciate your help.'}],vocab,slow:phrase,challenge:'In your own words, respond politely to this situation: '+l.name+'.',tip:'Use a friendly tone. Try speaking once slowly, then again at a natural pace.'};
}
function lessonDialogue(l){const e=lessonExtras(l);return `<div class="card enriched-card"><h2>💬 Guided Conversation · 4 Turns</h2><p class="muted">Practice an everyday American English exchange. Tap a line to hear it.</p><div class="turn-list">${e.turns.map((t,i)=>`<button class="dialogue-turn ${t.who==='You'?'student-turn':''}" onclick="speak(lessonExtras(lessons[selectedLesson]).turns[${i}].line)"><span class="turn-speaker">${esc(t.who)}</span><span>${esc(t.line)}</span><span aria-hidden="true">🔊</span></button>`).join('')}</div><button class="btn secondary" onclick="playFullDialogue()">▶ Play full dialogue</button></div><div class="card enriched-card"><h2>🧠 Vocabulary & Pronunciation</h2><p class="muted">Useful words from today's expression. Listen and repeat.</p><div class="vocab-chips">${e.vocab.map(w=>`<button class="vocab-chip" onclick="speak('${w}')">${esc(w)} 🔊</button>`).join('')}</div><p>${esc(e.tip)}</p><div class="row"><button class="btn secondary" onclick="speakSlow(lessons[selectedLesson].word)">🐢 Slow pronunciation</button><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">🔊 Natural speed</button></div></div><div class="card enriched-card"><h2>🎯 Real-life Speaking Challenge</h2><p>${esc(e.challenge)}</p><p class="muted">Try saying your own response out loud before using the microphone. Automatic speech recognition is not a pronunciation grade.</p><button class="btn secondary" onclick="listen()">🎙️ Practice response</button></div>`}
function speakSlow(text){if(!('speechSynthesis' in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.72;speechSynthesis.speak(u)}
let fullDialogueTimer=null;function playFullDialogue(){stopScene();const turns=lessonExtras(lessons[selectedLesson]).turns;let i=0;function next(){if(i>=turns.length)return;const u=new SpeechSynthesisUtterance(turns[i++].line);u.lang='en-US';u.rate=.88;u.onend=()=>{fullDialogueTimer=setTimeout(next,350)};speechSynthesis.speak(u)}if('speechSynthesis'in window)next()}
function lessonSlug(name){return name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function checkLesson(){if(choice<0){feedback='Choose an answer first.';render();return}let l=lessons[selectedLesson];if(choice===l.correct){let first=award('lesson'+selectedLesson,40);feedback='✅ Correct! '+(first?'You earned 40 XP.':'You already completed this lesson.')}else feedback='Try again. Read the lesson and choose the most natural English sentence.';render()}
function checkMission(){if(missionChoice<0){missionFeedback='Choose an answer first.';render();return}let p=places[selectedPlace];if(missionChoice===p.correct){let first=!state.missions.includes(p.id);if(first){state.missions.push(p.id);state.xp+=30;save()}missionFeedback='🎉 Mission complete! '+(first?'+30 XP. ':'')+'Character replies: “'+esc(p.reply)+'”'}else missionFeedback='Try again. Think about what would sound polite and natural in this situation.';render()}
function listen(){let R=window.SpeechRecognition||window.webkitSpeechRecognition;let el=document.getElementById('speechResult');if(!R){if(el)el.textContent='Speech recognition is unavailable in this browser. Try a supported browser or practice by listening and repeating.';return}let r=new R();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{let t=e.results[0][0].transcript;let node=document.getElementById('speechResult');if(node)node.textContent='You said: '+t+' (transcription only; not a pronunciation grade)'};r.onerror=e=>{let node=document.getElementById('speechResult');if(node)node.textContent='Microphone error: '+e.error};r.start();if(el)el.textContent='Listening... Please speak now.'}
render();

let sceneTimer=null;function stopScene(){if(fullDialogueTimer)clearTimeout(fullDialogueTimer);if(sceneTimer)clearTimeout(sceneTimer);sceneTimer=null;if('speechSynthesis'in window)speechSynthesis.cancel();}function playScene(){stopScene();const l=lessons[selectedLesson];const el=document.getElementById('sceneBubble');if(!el)return;el.textContent='Hello! Welcome. How can I help you?';speak('Hello! Welcome. How can I help you?');sceneTimer=setTimeout(()=>{const current=document.getElementById('sceneBubble');if(current){current.textContent=l.word;speak(l.word)}},3000)}


/* Curated level-specific teaching studio. Offline, no paid API. */
const masteryCurriculum={
'Starter':{topic:'Meeting a new neighbor',grammar:'I am / You are / My name is',explanation:'Use “I am” to introduce yourself. Use “My name is” before a name.',my:'မိမိကိုယ်ကို မိတ်ဆက်ရာတွင် I am နှင့် My name is ကို သုံးပါ။',lines:[['Neighbor','Hi! I’m Sam. What’s your name?','မင်္ဂလာပါ။ ကျွန်တော် ဆမ်ပါ။ နာမည်ဘယ်လိုခေါ်လဲ။'],['You','My name is May. Nice to meet you!','ကျွန်မနာမည် မေပါ။ တွေ့ရတာ ဝမ်းသာပါတယ်။'],['Neighbor','Nice to meet you too. Are you new here?','ကျွန်တော်လည်း ဝမ်းသာပါတယ်။ ဒီကို အသစ်ရောက်တာလား။'],['You','Yes, I just moved here.','ဟုတ်ပါတယ်။ အခုမှ ပြောင်းလာတာပါ။']],quiz:['What is a friendly introduction?',['Give me your name!','My name is May. Nice to meet you.','I moved tomorrow.'],1],expression:['Nice to meet you','တွေ့ရတာ ဝမ်းသာပါတယ်','Use when meeting someone for the first time.'],write:'Write 2 sentences introducing yourself and where you live.',model:'Hi, my name is May. I live in North Carolina.'},
'Beginner':{topic:'Ordering at a coffee shop',grammar:'Could I have + item + please?',explanation:'“Could I have…” is a polite way to order. “For here” means you will stay; “to go” means takeaway.',my:'ယဉ်ကျေးစွာ မှာယူရန် Could I have... please? ကို သုံးပါ။',lines:[['Barista','Good morning! What can I get started for you?','မင်္ဂလာနံနက်ခင်းပါ။ ဘာမှာမလဲ။'],['You','Could I have a medium latte, please?','လတ်တေးအလတ်တစ်ခွက် ရနိုင်မလား။'],['Barista','Sure! Is that for here or to go?','ရပါတယ်။ ဒီမှာသောက်မှာလား၊ ယူသွားမှာလား။'],['You','To go, please. Thank you!','ယူသွားမှာပါ။ ကျေးဇူးတင်ပါတယ်။']],quiz:['What does “to go” mean?',['Eat or drink somewhere else','Stay in the café','Cancel the order'],0],expression:['What can I get started for you?','ဘာမှာပေးရမလဲ','Common friendly service expression.'],write:'Order a drink politely and say whether it is for here or to go.',model:'Could I have a small tea, please? To go, please.'},
'Elementary':{topic:'Finding a bus stop',grammar:'Excuse me, could you tell me where…?',explanation:'Begin with “Excuse me” and ask a complete question. “Across from” means on the opposite side.',my:'လမ်းမေးမည်ဆိုပါက Excuse me ဖြင့် စတင်ပြီး ယဉ်ကျေးစွာ မေးပါ။',lines:[['Traveler','Excuse me, where is the nearest bus stop?','တဆိတ်လောက်ပါ။ အနီးဆုံး ဘတ်စ်ကားမှတ်တိုင် ဘယ်မှာလဲ။'],['Local','It’s across from the library.','စာကြည့်တိုက်ရဲ့ မျက်နှာချင်းဆိုင်မှာပါ။'],['Traveler','Is it within walking distance?','လမ်းလျှောက်သွားလို့ ရနိုင်မလား။'],['Local','Yes, about five minutes on foot.','ရပါတယ်။ ငါးမိနစ်လောက်ပါ။']],quiz:['“Across from the library” means…',['Inside the library','Opposite the library','Behind the library'],1],expression:['Within walking distance','လမ်းလျှောက်သွားလို့ရတဲ့အကွာအဝေး','Useful when asking about travel.'],write:'Ask someone how to get to a train station.',model:'Excuse me, could you tell me how to get to the train station?'},
'Intermediate':{topic:'Asking for a workplace update',grammar:'Could you + verb…? / I’ll + verb',explanation:'“Could you…” softens a request. “I’ll” is a common contraction of “I will.”',my:'အလုပ်ခွင်တွင် ယဉ်ကျေးသော တောင်းဆိုမှုအတွက် Could you…? ကို သုံးပါ။',lines:[['Manager','Could you give me a quick update on the project?','Project အခြေအနေကို အကျဉ်းချုပ် ပြောပြပေးနိုင်မလား။'],['You','Sure. We finished the first draft yesterday.','ရပါတယ်။ မနေ့က ပထမမူကြမ်း ပြီးသွားပါပြီ။'],['Manager','Great. Can you send it by noon?','ကောင်းပါတယ်။ နေ့လယ် ၁၂ နာရီမတိုင်ခင် ပို့နိုင်မလား။'],['You','Absolutely. I’ll email it shortly.','ရပါတယ်။ မကြာခင် အီးမေးလ်ပို့ပါမယ်။']],quiz:['What does “by noon” mean?',['At any time tonight','No later than 12 p.m.','After midnight'],1],expression:['Give me a quick update','အခြေအနေ အကျဉ်းချုပ် ပြောပြပါ','Common workplace phrase.'],write:'Write a polite message requesting an update from a coworker.',model:'Hi Alex, could you send me a quick update on the report by noon? Thanks!'},
'Upper Intermediate':{topic:'Resolving a billing problem',grammar:'I understand…, however… / Would it be possible…?',explanation:'Acknowledge the other person before presenting a concern. This is assertive without sounding rude.',my:'ပြဿနာဖြေရှင်းရာတွင် တစ်ဖက်လူကို နားလည်ကြောင်း အရင်ပြောပြီးမှ မိမိအချက်ကို တင်ပြပါ။',lines:[['Customer','I think there may be an error on my bill.','ကျွန်တော့် ဘေလ်မှာ အမှားရှိနိုင်တယ်ထင်ပါတယ်။'],['Agent','I’m sorry about that. Could you explain?','စိတ်မကောင်းပါဘူး။ ရှင်းပြပေးနိုင်မလား။'],['Customer','I was charged twice for the same item.','ပစ္စည်းတစ်ခုတည်းအတွက် နှစ်ခါကောက်ခံထားပါတယ်။'],['Agent','Thanks for pointing that out. Let me check.','ထောက်ပြပေးလို့ ကျေးဇူးပါ။ စစ်ကြည့်ပါမယ်။']],quiz:['What does “charged twice” mean?',['Billed two times','Given two gifts','Asked two questions'],0],expression:['Point that out','အချက်တစ်ခုကို ထောက်ပြသည်','Useful in polite problem-solving.'],write:'Write a respectful complaint about being charged twice.',model:'Hello, I noticed I was charged twice for one item. Would you please review my bill?'},
'Advanced':{topic:'Negotiating a project deadline',grammar:'Would you be open to…? / Provided that…',explanation:'Use conditional language to negotiate collaboratively rather than demand a change.',my:'ညှိနှိုင်းရာတွင် Would you be open to…? ကဲ့သို့ နူးညံ့သော စကားအသုံးအနှုန်းကို သုံးပါ။',lines:[['Lead','We need the proposal by Friday.','သောကြာနေ့မတိုင်ခင် အဆိုပြုလွှာ လိုပါတယ်။'],['You','Would you be open to extending the deadline?','သတ်မှတ်ရက်ကို တိုးပေးဖို့ စဉ်းစားနိုင်မလား။'],['Lead','What timeline would you suggest?','ဘယ်အချိန်အထိ အကြံပြုချင်လဲ။'],['You','Monday, provided that we confirm the scope today.','ဒီနေ့ အလုပ်အတိုင်းအတာ အတည်ပြုနိုင်ရင် တနင်္လာနေ့ပါ။']],quiz:['“Provided that” introduces…',['A condition','A location','A greeting'],0],expression:['Would you be open to…?','စဉ်းစားပေးနိုင်မလား','A diplomatic negotiation opener.'],write:'Propose a revised deadline and explain a condition.',model:'Would you be open to moving the deadline to Monday, provided that we finalize the scope today?'},
'Expert':{topic:'Diplomatic disagreement',grammar:'While I appreciate…, I have reservations about…',explanation:'Concede a valid point, then express reservations with evidence. Avoid dismissive absolutes.',my:'သဘောမတူသည့်အခါ တစ်ဖက်၏ ကောင်းသောအချက်ကို အသိအမှတ်ပြုပြီး အကြောင်းပြချက်ဖြင့် ပြောပါ။',lines:[['Colleague','I propose launching the new system next week.','စနစ်အသစ်ကို နောက်အပတ် စတင်ဖို့ အဆိုပြုပါတယ်။'],['You','I appreciate the urgency, but I have some reservations.','အရေးကြီးတာ နားလည်ပေမယ့် စိုးရိမ်ချက်အချို့ ရှိပါတယ်။'],['Colleague','Could you elaborate on your concerns?','စိုးရိမ်ချက်တွေကို အသေးစိတ် ပြောပြနိုင်မလား။'],['You','We may need additional testing to reduce risk.','အန္တရာယ်လျှော့ဖို့ စမ်းသပ်မှု ထပ်လိုနိုင်ပါတယ်။']],quiz:['“I have reservations” here means…',['I booked seats','I have concerns','I am certain'],1],expression:['I have some reservations','စိုးရိမ်ချက်အချို့ရှိသည်','Formal, diplomatic disagreement.'],write:'Disagree with a rushed plan while acknowledging its benefits.',model:'I appreciate the urgency; however, I have reservations about launching without further testing.'},
'Pro':{topic:'Leading a cross-team decision',grammar:'To align on… / The trade-off is… / Our next step is…',explanation:'Summarize the decision, name a trade-off, and assign clear ownership and a deadline.',my:'ခေါင်းဆောင်မှုဆိုင်ရာ ဆွေးနွေးပွဲတွင် ဆုံးဖြတ်ချက်၊ အားသာချက်/အားနည်းချက်နှင့် တာဝန်ယူသူကို ရှင်းလင်းစွာ သတ်မှတ်ပါ။',lines:[['Director','What is your recommendation?','သင့်အကြံပြုချက်က ဘာလဲ။'],['You','I recommend a phased rollout to manage risk.','အန္တရာယ်လျှော့ဖို့ အဆင့်လိုက် စတင်ဖို့ အကြံပြုပါတယ်။'],['Director','What is the main trade-off?','အဓိက အလဲအလှယ်ရမယ့်အချက်က ဘာလဲ။'],['You','It takes longer, but gives us time to validate results.','အချိန်ပိုယူပေမယ့် ရလဒ်စစ်ဖို့ အချိန်ရပါတယ်။']],quiz:['A “trade-off” is…',['A compromise between competing benefits','A greeting','A fixed legal requirement'],0],expression:['Phased rollout','အဆင့်လိုက် စတင်အသုံးပြုခြင်း','Common in project leadership.'],write:'Summarize a decision, trade-off, owner, and deadline.',model:'We agreed to a phased rollout. The trade-off is a longer timeline with lower risk. Maya will lead testing by Friday.'}
};

/* v1.2: individual lesson practice generated from each lesson's own authored material.
   All activities run locally; no account or paid service is required. */
function individualStudio(l){
 const id=selectedLesson, key='individual-'+id, draft=state.writing[key]||'';
 const sentence=l.word.trim(), meaning=l.mm, title=l.name;
 const chunks=sentence.replace(/[.!?]+$/,'').split(/\s+/);
 const missingIndex=Math.min(chunks.length-1,Math.max(0,Math.floor(chunks.length/2)));
 const hiddenWord=chunks[missingIndex].replace(/[^\w'-]/g,'');
 const cloze=chunks.map((w,i)=>i===missingIndex?'_____':w).join(' ');
 return `<section class="individual-studio" aria-label="Individual lesson practice">
 <div class="studio-intro"><span class="tag">LESSON ${id+1} · PERSONAL PRACTICE</span><h2>Practice: ${esc(title)}</h2><p>ဒီသင်ခန်းစာအတွက် သီးခြားလေ့ကျင့်ခန်းများ · Learn → Listen → Read → Speak → Write → Review</p></div>
 <div class="studio-two">
 <div class="card"><h3>🎧 Listen & Fill the Gap</h3><p>Listen without looking, then fill in the missing word.</p><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">▶ Listen</button><button class="btn secondary" onclick="speakSlow(lessons[selectedLesson].word)">🐢 Slow</button><p class="cloze">${esc(cloze)}</p><label for="gap-${id}">Missing word</label><input class="field" id="gap-${id}" autocomplete="off" placeholder="Type the missing word"><button class="btn" onclick="checkGap()">Check listening</button><p id="gap-feedback" aria-live="polite"></p></div>
 <div class="card"><h3>📖 Read & Understand</h3><p class="reading-quote">${esc(l.text)}</p><p><strong>Key expression:</strong> ${esc(sentence)}</p><p class="muted">မြန်မာ — ${esc(meaning)}</p><p>${esc(l.question)}</p><div class="choices">${l.opts.map((o,i)=>`<button class="choice" onclick="checkIndividualReading(${i})">${esc(o)}</button>`).join('')}</div><p id="individual-reading-feedback" aria-live="polite"></p></div>
 <div class="card"><h3>🎙️ Speak in Context</h3><p>Situation: <strong>${esc(title)}</strong></p><p>Practice saying: <strong>${esc(sentence)}</strong></p><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">🔊 Hear it</button><button class="btn" onclick="listen()">🎙️ Try microphone</button><p class="muted">Speech recognition is optional and is not a pronunciation grade.</p></div>
 <div class="card"><h3>✍️ Write Your Own Answer</h3><p>${esc(l.writing)}</p><textarea id="individual-writing" class="field" rows="5" placeholder="Write your English here..." oninput="state.writing['individual-'+selectedLesson]=this.value;save()">${esc(draft)}</textarea><p class="muted">Saved on this device. Compare your answer with the model expression, not an AI grade.</p><button class="btn secondary" onclick="document.getElementById('individual-model').hidden=false">Show example expression</button><p id="individual-model" hidden>${esc(sentence)}</p></div>
 </div><div class="card"><h3>🧠 Review & Remember</h3><p>Say the expression three times. Then explain what it means in Burmese and write one new sentence using the same pattern.</p><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">↻ Repeat</button><p class="muted">${esc(meaning)}</p></div></section>`;
}
function checkGap(){const l=lessons[selectedLesson];const chunks=l.word.trim().replace(/[.!?]+$/,'').split(/\s+/);const index=Math.min(chunks.length-1,Math.max(0,Math.floor(chunks.length/2)));const answer=chunks[index].replace(/[^\w'-]/g,'').toLowerCase();const input=document.getElementById('gap-'+selectedLesson);const feedback=document.getElementById('gap-feedback');if(!input||!feedback)return;const typed=input.value.trim().replace(/[^\w'-]/g,'').toLowerCase();feedback.textContent=typed===answer?'✅ Correct! Well done.':'Try again. Listen once more.'}
function checkIndividualReading(i){const l=lessons[selectedLesson];const el=document.getElementById('individual-reading-feedback');if(el)el.textContent=i===l.correct?'✅ Correct. '+l.word:'Not quite. Read the explanation and try again.'}

function masteryStudio(l){const d=masteryCurriculum[l.level];if(!d)return '';const key='mastery-'+selectedLesson;const draft=state.writing[key]||'';return `<section class="mastery-studio"><div class="mastery-heading"><span class="tag">✨ Curated ${esc(l.level)} Studio</span><h2>${esc(d.topic)}</h2><p class="muted">Extra real-life practice for this level · English + မြန်မာ</p></div><div class="card"><h3>📘 Grammar in Context</h3><strong>${esc(d.grammar)}</strong><p>${esc(d.explanation)}</p><p class="muted">${esc(d.my)}</p></div><div class="card"><h3>🎧 Listening & Reading · 4 Turns</h3><p class="muted">Tap each dialogue line to hear American English.</p>${d.lines.map((t,i)=>`<button class="mastery-turn" onclick="speak(masteryCurriculum[lessons[selectedLesson].level].lines[${i}][1])"><span><strong>${esc(t[0])}</strong><span>${esc(t[1])}</span><small>${esc(t[2])}</small></span><span aria-hidden="true">🔊</span></button>`).join('')}<button class="btn secondary" onclick="playMasteryDialogue()">▶ Play all</button> <button class="btn secondary" onclick="stopScene()">■ Stop</button></div><div class="card"><h3>💡 Everyday Expression</h3><strong>${esc(d.expression[0])}</strong><p>${esc(d.expression[1])}</p><p class="muted">${esc(d.expression[2])}</p><button class="btn secondary" onclick="speak(masteryCurriculum[lessons[selectedLesson].level].expression[0])">🔊 Listen</button></div><div class="card"><h3>🧠 Listening Check</h3><p>${esc(d.quiz[0])}</p><div class="choices">${d.quiz[1].map((o,i)=>`<button class="choice" onclick="checkMastery(${i})">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><p id="mastery-feedback" aria-live="polite"></p></div><div class="card"><h3>✍️ Writing Challenge</h3><p>${esc(d.write)}</p><textarea id="mastery-writing" class="field" placeholder="Write your answer here..." oninput="state.writing['mastery-'+selectedLesson]=this.value;save()">${esc(draft)}</textarea><button class="btn secondary" onclick="document.getElementById('mastery-model').hidden=false">👁 Show sample answer</button><p id="mastery-model" hidden>${esc(d.model)}</p><p class="muted">Your writing saves locally. Sample answers are for comparison, not automatic grading.</p></div><div class="card"><h3>🎙️ Speaking Role-play</h3><p>Play the dialogue, then take the “You” role aloud.</p><button class="btn secondary" onclick="speakSlow(masteryCurriculum[lessons[selectedLesson].level].lines[1][1])">🐢 Slow example</button> <button class="btn" onclick="listen()">🎙️ Speak</button><p id="speechResult" aria-live="polite">Recognition depends on your browser. This is not a pronunciation grade.</p></div></section>`}
function checkMastery(i){const d=masteryCurriculum[lessons[selectedLesson].level];const e=document.getElementById('mastery-feedback');if(e)e.textContent=i===d.quiz[2]?'✅ Correct! Great listening.':'Try again. Listen to the conversation once more.'}
function playMasteryDialogue(){stopScene();const d=masteryCurriculum[lessons[selectedLesson].level];if(!('speechSynthesis' in window))return;d.lines.forEach(t=>{const u=new SpeechSynthesisUtterance(t[1]);u.lang='en-US';u.rate=.88;speechSynthesis.speak(u)})}


/* v1.3 — offline-first conversation rehearsal and spaced review.
   No remote AI calls, speech grading claims, or paid services. */
function conversationLab(l){
 const good=l.opts[l.correct], line=l.word;
 return `<section class="conversation-lab card" aria-label="Conversation rehearsal">
 <span class="tag">🎭 REAL-LIFE ROLE PLAY</span><h2>${esc(l.name)} — Your turn</h2>
 <p class="muted">Practice a short scenario based on this lesson. This is guided practice, not an AI chat.</p>
 <div class="role-turn"><strong>Guide:</strong> ${esc(l.question)} <button class="mini-audio" onclick="speak(lessons[selectedLesson].question)" aria-label="Hear the question">🔊</button></div>
 <div class="role-turn learner"><strong>You:</strong> <span id="role-answer">Think of your own answer before revealing the model.</span></div>
 <div class="row"><button class="btn secondary" onclick="document.getElementById('role-answer').textContent=lessons[selectedLesson].opts[lessons[selectedLesson].correct]">👁 Reveal model</button><button class="btn secondary" onclick="speak(lessons[selectedLesson].opts[lessons[selectedLesson].correct])">🔊 Hear model</button><button class="btn" onclick="listen()">🎙️ Practice speaking</button></div>
 <p class="muted">Key phrase: ${esc(line)} · ${esc(l.mm)}</p>
 </section>`;
}
function reviewMeta(id){try{const x=JSON.parse(state.writing['review-'+id]||'null');return x&&Number.isFinite(x.due)&&Number.isInteger(x.stage)?x:null}catch{return null}}
function reviewLab(l){
 const m=reviewMeta(selectedLesson),due=!m||m.due<=Date.now();
 const next=m&&!due?new Date(m.due).toLocaleDateString():'';
 return `<section class="review-lab card" aria-label="Spaced repetition">
 <span class="tag">🧠 SPACED REVIEW</span><h2>Remember: ${esc(l.name)}</h2>
 <p>${due?'Ready for review. Try recalling the expression before you reveal it.':'Next review: '+esc(next)}</p>
 <div class="review-prompt">${esc(l.mm)}</div>
 <p id="review-reveal" hidden class="review-answer">${esc(l.word)}</p>
 <div class="row"><button class="btn secondary" onclick="document.getElementById('review-reveal').hidden=false">Show English answer</button><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">🔊 Listen</button></div>
 <div class="row review-rating"><button class="btn secondary" onclick="rateReview(false)">↻ Need practice</button><button class="btn" onclick="rateReview(true)">✓ Remembered</button></div>
 <p id="review-status" aria-live="polite" class="muted">Your review schedule is saved locally and included in progress exports.</p>
 </section>`;
}
function rateReview(remembered){
 const id=selectedLesson,prev=reviewMeta(id),stage=remembered?Math.min(5,(prev?.stage||0)+1):0;
 const days=[0,1,3,7,14,30][stage];
 const due=Date.now()+(remembered?days*86400000:10*60000);
 state.writing['review-'+id]=JSON.stringify({stage,due});save();
 const el=document.getElementById('review-status');
 if(el)el.textContent=remembered?`✓ Saved. Next review in ${days} day${days===1?'':'s'}.`:'Saved. Review again in 10 minutes.';
}


/* v1.4 — topic-specific four-turn scenario rehearsal for every lesson.
   The target sentence and context are from the authored lesson; surrounding
   prompts are guided templates, not AI-generated conversations or video. */
function scenarioForLesson(l){
 const topic=l.name, target=l.word, level=l.level;
 const work=/work|meeting|proposal|deadline|manager|team|project|report|negotiat|lead|professional|presentation|interview/i.test(topic);
 const travel=/airport|flight|train|bus|transport|direction|driv|taxi|hotel|trip|travel|station/i.test(topic);
 const service=/restaurant|coffee|grocery|shop|store|bank|post office|appointment|hospital|doctor|housing|billing|refund|customer/i.test(topic);
 const social=/friend|family|neighbor|greeting|introduction|small talk|weekend|party|social|phone/i.test(topic);
 const scene=work?'a workplace conversation':travel?'a travel situation':service?'a customer-service conversation':social?'a friendly conversation':'an everyday American English conversation';
 const role=work?'Coworker':travel?'Local guide':service?'Staff member':social?'Neighbor':'Conversation partner';
 const opener=work?'Hi! Do you have a moment to discuss '+topic.toLowerCase()+'?':travel?'Excuse me, can I help you with '+topic.toLowerCase()+'?':service?'Hello! How can I help you today?':social?'Hi there! How is your day going?':'Hi! What would you like to talk about today?';
 const reply=work?'Thanks for explaining. What should we do next?':travel?'Of course. Is there anything else you need?':service?'Certainly. Let me see what I can do.':social?'That sounds great! Tell me more.':'Thanks for sharing that. Could you give an example?';
 const close=work?'Thanks. I will follow up with the next steps.':travel?'Thank you for your help!':service?'Thank you. I appreciate your help.':social?'It was nice talking with you!':'Thank you for the conversation.';
 return {scene,lines:[[role,opener],['You',target],[role,reply],['You',close]],role};
}
function scenarioStudio(l){
 const d=scenarioForLesson(l), id=selectedLesson, key='scenario-notes-'+id;
 return `<section class="scenario-studio" aria-label="Real-life scenario rehearsal"><div class="card scenario-panel"><span class="tag">🎭 LESSON ${id+1} · REAL-LIFE REHEARSAL</span><h2>${esc(l.name)} — Conversation Scene</h2><p class="muted">Practice ${esc(d.scene)}. This is a guided simulation with browser narration, not a recorded video or live AI.</p><div class="scenario-stage" aria-hidden="true"><div class="scenario-scene-icon">${/work|meeting|project|team/i.test(l.name)?'🏢':/travel|bus|train|direction|airport/i.test(l.name)?'🗺️':/coffee|restaurant|food|grocery/i.test(l.name)?'☕':'💬'}</div><div class="scenario-scene-copy"><strong>${esc(l.name)}</strong><small>Listen • Repeat • Role-play</small></div></div><div class="scenario-lines">${d.lines.map((t,i)=>`<button type="button" class="scenario-line ${i%2?'scenario-you':''}" onclick="playScenarioLine(${i})"><span><strong>${esc(t[0])}</strong><span>${esc(t[1])}</span></span><span aria-hidden="true">🔊</span></button>`).join('')}</div><div class="row"><button class="btn" onclick="playScenarioAll()">▶ Play dialogue</button><button class="btn secondary" onclick="stopScene()">■ Stop</button><button class="btn secondary" onclick="playScenarioLine(1,true)">🐢 Slow my line</button></div><p><strong>မြန်မာ:</strong> ${esc(l.mm)}</p><h3>✍️ Your turn</h3><p>${esc(l.writing)}</p><textarea class="field" id="scenario-notes" rows="3" oninput="state.writing['${key}']=this.value;save()" placeholder="Write a natural reply in your own words...">${esc(state.writing[key]||'')}</textarea><div class="row"><button class="btn secondary" onclick="showScenarioChecklist()">✓ Self-check writing</button><button class="btn secondary" onclick="listen()">🎙️ Practice speaking</button></div><div id="scenario-checklist" class="scenario-checklist" hidden><strong>Self-review checklist (not automatic grading)</strong><p>□ Did I answer the situation clearly?</p><p>□ Did I use a polite, natural expression?</p><p>□ Did I check spelling and punctuation?</p><p>□ Can I say my answer aloud without reading?</p><p><strong>Model expression:</strong> ${esc(l.word)}</p></div><p id="speechResult" aria-live="polite" class="muted">Speech recognition availability depends on your browser.</p></div></section>`;
}
function playScenarioLine(i,slow=false){const l=lessons[selectedLesson];const t=scenarioForLesson(l).lines[i];if(slow)speakSlow(t[1]);else speak(t[1]);}
function playScenarioAll(){stopScene();if(!('speechSynthesis' in window))return;for(const t of scenarioForLesson(lessons[selectedLesson]).lines){const u=new SpeechSynthesisUtterance(t[1]);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u)}}
function showScenarioChecklist(){const el=document.getElementById('scenario-checklist');if(el)el.hidden=!el.hidden;}


/* v1.5: captioned mini-clip player. Each lesson uses its own scenario and
   requires no network, paid speech API, or pre-recorded video. */
let clipRun=0, clipIndex=0, clipPaused=false;
function storyboardStudio(l){
 const d=scenarioForLesson(l);
 return `<section class="storyboard-studio card" aria-label="Captioned conversation clip">
 <span class="tag">🎞️ CONVERSATION MINI-CLIP · LESSON ${selectedLesson+1}</span>
 <h2>${esc(l.name)} — Watch, Listen & Repeat</h2>
 <p class="muted">Four-scene animated caption lesson. Browser voice is optional; this is not an MP4 recording.</p>
 <div class="clip-stage" id="clipStage" role="group" aria-label="Animated dialogue captions">
 <div class="clip-backdrop"><span aria-hidden="true">${/work|meeting|project|team/i.test(l.name)?'🏢':/travel|bus|train|direction|airport/i.test(l.name)?'🚆':/coffee|restaurant|food|grocery/i.test(l.name)?'☕':'🌆'}</span></div>
 <div class="clip-caption"><small id="clipSpeaker">Ready to begin</small><strong id="clipLine">Press Play to watch the conversation.</strong></div>
 </div>
 <div class="clip-track" aria-hidden="true"><div id="clipProgress"></div></div>
 <div class="row"><button class="btn" onclick="startMiniClip()">▶ Play clip</button><button class="btn secondary" onclick="pauseMiniClip()">⏸ Pause</button><button class="btn secondary" onclick="replayMiniClip()">↻ Replay</button><button class="btn secondary" onclick="stopMiniClip()">■ Stop</button></div>
 <p class="muted">Captions remain visible without audio. Use the scenario dialogue below for line-by-line practice.</p>
 </section>`;
}
function setClipFrame(i){
 const d=scenarioForLesson(lessons[selectedLesson]);const t=d.lines[i];
 const speaker=document.getElementById('clipSpeaker'),line=document.getElementById('clipLine'),progress=document.getElementById('clipProgress');
 if(!speaker||!line||!progress)return false;
 speaker.textContent=`Scene ${i+1} of ${d.lines.length} · ${t[0]}`;
 line.textContent=t[1];progress.style.width=`${(i+1)/d.lines.length*100}%`;
 const stage=document.getElementById('clipStage');stage.classList.remove('clip-enter');void stage.offsetWidth;stage.classList.add('clip-enter');return true;
}
function stopMiniClip(){clipRun++;clipPaused=false;clipIndex=0;if('speechSynthesis'in window)speechSynthesis.cancel();}
function pauseMiniClip(){clipPaused=true;clipRun++;if('speechSynthesis'in window)speechSynthesis.cancel();}
function replayMiniClip(){stopMiniClip();startMiniClip();}
function startMiniClip(){
 if(!clipPaused)clipIndex=0;clipPaused=false;const run=++clipRun;
 function advance(){if(run!==clipRun)return;const d=scenarioForLesson(lessons[selectedLesson]);if(clipIndex>=d.lines.length){clipIndex=0;return;}
 const i=clipIndex++;if(!setClipFrame(i))return;
 const next=()=>{if(run===clipRun)setTimeout(advance,550)};
 if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(d.lines[i][1]);u.lang='en-US';u.rate=.82;u.onend=next;u.onerror=next;speechSynthesis.speak(u)}else setTimeout(next,2400);
 }advance();
}
